    12	public class Main {
    13	    public static void main(String[] args) {
    14	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
    15	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
    16	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
    17	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
