    41	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    42	        app.get("/reservations/{id}/document", reservationController::getDocument);
    43	
    44	        app.get("/messages", messageController::listMessages);
    45	
    46	        app.get("/reports/occupancy", reportController::occupancyReport);
    47	        app.get("/reports/revenue", reportController::revenueReport);
    48	        app.get("/reports/tourism-tax", reportController::tourismTaxReport);
    49	        app.get("/reports/rate-plans", reportController::ratePlansReport);
    50	
    51	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
    52	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
    53	        });
    54	
    55	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
    56	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
    57	        });
    58	
    59	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
    60	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
    61	        });
    62	
    63	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
    64	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for current reservation status"));
    65	        });
    66	
    67	        app.exception(CapacityExceededException.class, (e, ctx) -> {
    68	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
    69	        });
