    15	
    16	public class ReservationController {
    17	    private final ReservationService reservationService;
    18	
    19	    public ReservationController() {
    20	        this.reservationService = new ReservationService();
    21	    }
    22	
    23	    public void createReservation(Context ctx) {
    24	        try {
    25	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
    26	
    27	            String roomNumber = getRequiredString(json, "roomNumber");
    28	            String guestName = getRequiredString(json, "guestName");
    29	            String guestEmail = getRequiredString(json, "guestEmail");
    30	            String guestCpf = getRequiredString(json, "guestCpf");
    31	            LocalDate checkIn = getRequiredDate(json, "checkIn");
    32	            LocalDate checkOut = getRequiredDate(json, "checkOut");
    33	            int guests = getRequiredInt(json, "guests");
    34	            RatePlan ratePlan = getRequiredEnum(json, "ratePlan", RatePlan.class);
    35	
    36	            Reservation reservation = reservationService.createReservation(
    37	                roomNumber, guestName, guestEmail, guestCpf,
    38	                checkIn, checkOut, guests, ratePlan
    39	            );
    40	
    41	            ctx.status(201).json(toJson(reservation));
    42	        } catch (InvalidRequestException e) {
    43	            throw e;
    44	        } catch (Exception e) {
    45	            throw new InvalidRequestException("Invalid request");
    46	        }
    47	    }
    48	
    49	    public void getReservation(Context ctx) {
    50	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    51	        Reservation reservation = reservationService.getReservation(id);
    52	        ctx.json(toJson(reservation));
    53	    }
    54	
    55	    public void confirmReservation(Context ctx) {
    56	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    57	        Reservation reservation = reservationService.confirmReservation(id);
    58	        ctx.json(toJson(reservation));
    59	    }
    60	
    61	    public void cancelReservation(Context ctx) {
    62	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    63	        Reservation reservation = reservationService.cancelReservation(id);
    64	        ctx.json(toJson(reservation));
    65	    }
    66	
    67	    public void checkIn(Context ctx) {
    68	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    69	        Reservation reservation = reservationService.checkIn(id);
    70	        ctx.json(toJson(reservation));
    71	    }
    72	
    73	    public void checkOut(Context ctx) {
    74	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    75	        Reservation reservation = reservationService.checkOut(id);
    76	        ctx.json(toDocument(reservation));
    77	    }
    78	
    79	    public void getDocument(Context ctx) {
    80	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    81	        Reservation reservation = reservationService.getReservation(id);
    82	        ctx.json(toDocument(reservation));
    83	    }
    84	
    85	    private Map<String, Object> toJson(Reservation r) {
    86	        Map<String, Object> json = new HashMap<>();
    87	        json.put("id", r.getId());
    88	        json.put("roomNumber", r.getRoomNumber());
    89	        json.put("guestName", r.getGuestName());
    90	        json.put("guestEmail", r.getGuestEmail());
    91	        json.put("guestCpf", r.getGuestCpf());
    92	        json.put("checkIn", DateUtils.formatISO(r.getCheckIn()));
    93	        json.put("checkOut", DateUtils.formatISO(r.getCheckOut()));
    94	        json.put("guests", r.getGuests());
    95	        json.put("ratePlan", r.getRatePlan().name());
    96	        json.put("nights", r.getNights());
    97	        json.put("subtotal", r.getSubtotal());
    98	        json.put("discount", r.getDiscount());
    99	        json.put("total", r.getTotal());
   100	        json.put("status", r.getStatus().name());
   101	        json.put("amountPaid", r.getAmountPaid());
   102	        json.put("refund", r.getRefund());
   103	        return json;
   104	    }
   105	
   106	    private Map<String, Object> toDocument(Reservation r) {
   107	        Map<String, Object> json = new HashMap<>();
   108	        json.put("title", "Comprovante de reserva");
   109	        json.put("reservationId", r.getId());
   110	        json.put("guestName", r.getGuestName());
   111	        json.put("guestCpf", r.getGuestCpf());
   112	        json.put("roomNumber", r.getRoomNumber());
   113	        json.put("roomType", new com.pousadamarealta.repository.RoomRepository()
   114	            .findByNumber(r.getRoomNumber()).get().getType().name());
   115	        json.put("checkIn", DateUtils.formatISO(r.getCheckIn()));
   116	        json.put("checkOut", DateUtils.formatISO(r.getCheckOut()));
   117	        json.put("nights", r.getNights());
   118	        json.put("subtotal", r.getSubtotal());
   119	        json.put("discount", r.getDiscount());
   120	        json.put("total", r.getTotal());
   121	        return json;
   122	    }
   123	
   124	    private String getRequiredString(JsonNode json, String field) {
   125	        if (!json.has(field) || json.get(field).isNull()) {
   126	            throw new InvalidRequestException("Missing field: " + field);
   127	        }
   128	        return json.get(field).asText();
   129	    }
   130	
   131	    private int getRequiredInt(JsonNode json, String field) {
   132	        if (!json.has(field) || json.get(field).isNull()) {
   133	            throw new InvalidRequestException("Missing field: " + field);
   134	        }
   135	        return json.get(field).asInt();
   136	    }
   137	
   138	    private LocalDate getRequiredDate(JsonNode json, String field) {
   139	        String dateStr = getRequiredString(json, field);
   140	        try {
   141	            return DateUtils.parseISO(dateStr);
   142	        } catch (DateTimeParseException e) {
   143	            throw new InvalidRequestException("Invalid date format: " + field);
   144	        }
   145	    }
   146	
   147	    private <T extends Enum<T>> T getRequiredEnum(JsonNode json, String field, Class<T> enumClass) {
   148	        String value = getRequiredString(json, field);
   149	        try {
   150	            return Enum.valueOf(enumClass, value);
   151	        } catch (IllegalArgumentException e) {
   152	            throw new InvalidRequestException("Invalid value for " + field);
   153	        }
   154	    }
   155	}
