    13	public class RatePlansReport extends BaseReport {
    14	    private final ReservationRepository reservationRepository;
    15	
    16	    public RatePlansReport() {
    17	        this.reservationRepository = new ReservationRepository();
    18	    }
    19	
    20	    public String generate(int year, int month) {
    21	        addTitleLine("rate-plans", String.format("%04d-%02d", year, month));
    22	        addHeaderLine("rate_plan", "reservations", "amount");
    23	
    24	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
    25	
    26	        Map<RatePlan, Integer> counts = new HashMap<>();
    27	        Map<RatePlan, BigDecimal> amounts = new HashMap<>();
    28	
    29	        for (RatePlan plan : RatePlan.values()) {
    30	            counts.put(plan, 0);
    31	            amounts.put(plan, BigDecimal.ZERO);
    32	        }
    33	
    34	        for (Reservation r : reservations) {
    35	            BigDecimal netAmount = r.getAmountPaid();
    36	            if (r.getRefund() != null) {
    37	                netAmount = netAmount.subtract(r.getRefund());
    38	            }
    39	
    40	            if (netAmount.compareTo(BigDecimal.ZERO) > 0) {
    41	                RatePlan plan = r.getRatePlan();
    42	                counts.put(plan, counts.get(plan) + 1);
    43	                amounts.put(plan, amounts.get(plan).add(netAmount));
    44	            }
    45	        }
    46	
    47	        int totalCount = 0;
    48	        BigDecimal totalAmount = BigDecimal.ZERO;
    49	
    50	        for (RatePlan plan : RatePlan.values()) {
    51	            int count = counts.get(plan);
    52	            BigDecimal amount = amounts.get(plan);
    53	
    54	            addDataLine(
    55	                plan.name(),
    56	                String.valueOf(count),
    57	                MoneyUtils.formatCSV(amount)
    58	            );
    59	
    60	            totalCount += count;
    61	            totalAmount = totalAmount.add(amount);
    62	        }
    63	
    64	        addDataLine("total", String.valueOf(totalCount), MoneyUtils.formatCSV(totalAmount));
    65	
    66	        return super.generate();
    67	    }
    68	}
