    28	
    29	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    30	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    31	                                        int guests, RatePlan ratePlan) {
    32	
    33	        Room room = roomRepository.findByNumber(roomNumber)
    34	            .orElseThrow(() -> new RoomNotFoundException());
    35	
    36	        if (guests < 1 || guests > room.getCapacity()) {
    37	            throw new CapacityExceededException();
    38	        }
    39	
    40	        if (!checkOut.isAfter(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(
    45	            roomNumber, checkIn, checkOut);
    46	
    47	        if (!conflicts.isEmpty()) {
    48	            throw new RoomUnavailableException();
    49	        }
    50	
    51	        Reservation reservation = new Reservation();
    52	        reservation.setRoomNumber(roomNumber);
    53	        reservation.setGuestName(guestName);
    54	        reservation.setGuestEmail(guestEmail);
    55	        reservation.setGuestCpf(guestCpf);
    56	        reservation.setCheckIn(checkIn);
    57	        reservation.setCheckOut(checkOut);
    58	        reservation.setGuests(guests);
    59	        reservation.setRatePlan(ratePlan);
    60	
    61	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    62	        reservation.setNights(nights);
    63	
    64	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
    65	        reservation.setSubtotal(subtotal);
    66	
    67	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    68	        reservation.setDiscount(discount);
    69	
    70	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    71	        reservation.setTotal(total);
    72	
    73	        return reservationRepository.save(reservation);
    74	    }
    75	
