    77	        return reservationRepository.findById(id)
    78	            .orElseThrow(() -> new ReservationNotFoundException());
    79	    }
    80	
    81	    public Reservation confirmReservation(Long id) {
    82	        Reservation reservation = getReservation(id);
    83	
    84	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    85	            throw new OperationNotAllowedException();
    86	        }
    87	
    88	        reservation.setStatus(ReservationStatus.CONFIRMED);
    89	        reservation.setAmountPaid(reservation.getTotal());
    90	        reservationRepository.save(reservation);
    91	
    92	        sendConfirmationEmail(reservation);
    93	
    94	        return reservation;
    95	    }
