    97	    public Reservation cancelReservation(Long id) {
    98	        Reservation reservation = getReservation(id);
    99	
   100	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   101	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   102	            throw new OperationNotAllowedException();
   103	        }
   104	
   105	        reservation.setStatus(ReservationStatus.CANCELLED);
