    49	    public BigDecimal calculateTourismTax(int guests, int nights) {
    50	        BigDecimal taxPerGuestPerNight = new BigDecimal("4.50");
    51	        BigDecimal totalGuests = new BigDecimal(guests);
    52	        BigDecimal totalNights = new BigDecimal(nights);
    53	        return MoneyUtils.round(taxPerGuestPerNight.multiply(totalGuests).multiply(totalNights));
    54	    }
    55	}

