    25	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    26	        BigDecimal subtotal = BigDecimal.ZERO;
    27	        LocalDate currentDate = checkIn;
    28	
    29	        while (currentDate.isBefore(checkOut)) {
    30	            BigDecimal nightPrice = calculateNightPrice(room, currentDate);
    31	            subtotal = subtotal.add(nightPrice);
    32	            currentDate = currentDate.plusDays(1);
    33	        }
    34	
    35	        return MoneyUtils.round(subtotal);
    36	    }
    37	
    38	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    39	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    40	            return MoneyUtils.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    41	        }
    42	        return BigDecimal.ZERO;
    43	    }
    44	
    45	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    46	        return MoneyUtils.round(subtotal.subtract(discount));
    47	    }
    48	
    49	    public BigDecimal calculateTourismTax(int guests, int nights) {
    50	        BigDecimal taxPerGuestPerNight = new BigDecimal("4.50");
    51	        BigDecimal totalGuests = new BigDecimal(guests);
    52	        BigDecimal totalNights = new BigDecimal(nights);
    53	        return MoneyUtils.round(taxPerGuestPerNight.multiply(totalGuests).multiply(totalNights));
    54	    }
    55	}

